export interface ApiUser { id: number | string; firstname: string; lastname?: string; username?: string; city?: string; country?: string; profile_url?: string; scopes?: string; last_sync_at?: string; strava_connected?: boolean; }
export interface ApiPreferences { language?: string; distance_unit?: string; elevation_unit?: string; temperature_unit?: string; week_starts_on?: number; theme?: string; }
export interface ApiSession { authenticated: boolean; user: ApiUser | null; preferences?: ApiPreferences; csrf_token: string; }
export interface ApiDashboard { user?: ApiUser; stats?: { total?: number; distance?: number; moving_time?: number; elevation?: number }; trend?: unknown[]; activities?: unknown[]; }
export interface ActivityPagination { limit: number; cursor: string | null; has_next: boolean; next_cursor: string | null; }
export interface ApiActivities { activities: unknown[]; count: number; pagination?: ActivityPagination; }
export interface ApiSegments { segments?: unknown[]; groups?: unknown[]; strava_segments?: unknown[]; }
export interface StravaAuthorization { authorization_url: string; }
export interface NormalizedMap { bounds: { south: number; west: number; north: number; east: number } | null; points: [number, number][]; geojson?: unknown; point_count: number; simplified: boolean; }
export interface ApiSegmentDetail { segment: Record<string, any>; map: NormalizedMap; ranking: { attempts: number; best_time: number | null; average_time: number | null; best_speed: number | null; top_efforts: any[] }; evolution: any[]; efforts_by_activity: any[]; goal: Record<string, any> | null; }
export interface ApiProfile { profile: ApiUser; preferences: ApiPreferences; }
export interface ApiShare { ok?: boolean; share_type?: string; token?: string; url?: string; expires_at?: string | null; hide_name?: boolean; hide_time?: boolean; hide_start?: boolean; }
export const API_BASE_URL = 'https://alon.one/sports/api/v1';

@Injectable({ providedIn: 'root' })
export class CsrfStore { readonly token = signal(''); set(token: string) { this.token.set(token || ''); } clear() { this.token.set(''); } }

@Injectable({ providedIn: 'root' })
export class ApiService {
  private readonly http = inject(HttpClient); readonly baseUrl = API_BASE_URL;
  session() { return this.http.get<ApiSession>(`${this.baseUrl}/auth/session`); }
  csrfToken() { return this.http.get<ApiSession>(`${this.baseUrl}/auth/csrf`); }
  stravaAuthorization() { return this.http.get<StravaAuthorization>(`${this.baseUrl}/auth/strava`); }
  dashboard() { return this.http.get<ApiDashboard>(`${this.baseUrl}/dashboard`); }
  activities(limit = 100, cursor?: string | null) { let params = new HttpParams().set('limit', limit); if (cursor) params = params.set('cursor', cursor); return this.http.get<ApiActivities>(`${this.baseUrl}/activities`, { params }); }
  activity(id: string) { return this.http.get<Record<string, unknown>>(`${this.baseUrl}/activities/${encodeURIComponent(id)}`); }
  activityMap(id: string) { return this.http.get<{ activity_id: string | number; map: NormalizedMap }>(`${this.baseUrl}/maps/activities/${encodeURIComponent(id)}`); }
  updateActivity(id: string, body: unknown) { return this.http.put<Record<string, unknown>>(`${this.baseUrl}/activities/${encodeURIComponent(id)}`, body); }
  activityNotes(id: string) { return this.http.get<Record<string, unknown>>(`${this.baseUrl}/activities/${encodeURIComponent(id)}/notes`); }
  updateActivityNotes(id: string, body: unknown) { return this.http.put<Record<string, unknown>>(`${this.baseUrl}/activities/${encodeURIComponent(id)}/notes`, body); }
  importActivity(body: FormData) { return this.http.post<Record<string, unknown>>(`${this.baseUrl}/activities/import`, body); }
  syncActivities() { return this.http.post<Record<string, unknown>>(`${this.baseUrl}/activities/sync`, {}); }
  deleteActivity(id: string) { return this.http.delete<Record<string, unknown>>(`${this.baseUrl}/activities/${encodeURIComponent(id)}`); }
  profile() { return this.http.get<ApiProfile>(`${this.baseUrl}/profile`); }
  updateProfile(body: unknown) { return this.http.put<{ ok: boolean; profile: ApiUser }>(`${this.baseUrl}/profile`, body); }
  updatePreferences(body: ApiPreferences) { return this.http.put<{ ok: boolean; preferences: ApiPreferences }>(`${this.baseUrl}/preferences`, body); }
  segments() { return this.http.get<ApiSegments>(`${this.baseUrl}/segments`); }
  createSegment(body: unknown) { return this.http.post<{ ok: boolean; id: string | number; segment: Record<string, unknown> }>(`${this.baseUrl}/segments`, body); }
  segment(id: string) { return this.http.get<Record<string, unknown>>(`${this.baseUrl}/segments/${encodeURIComponent(id)}`); }
  segmentDetail(id: string) { return this.http.get<ApiSegmentDetail>(`${this.baseUrl}/segments/${encodeURIComponent(id)}/detail`); }
  statistics() { return this.http.get<Record<string, any>>(`${this.baseUrl}/statistics`); }
  analysis() { return this.http.get<Record<string, any>>(`${this.baseUrl}/analysis`); }
  getShare(id: string) { return this.http.get<ApiShare>(`${this.baseUrl}/activities/${encodeURIComponent(id)}/share`); }
  createShare(id: string, body: unknown) { return this.http.post<ApiShare>(`${this.baseUrl}/activities/${encodeURIComponent(id)}/share`, body); }
  updateShare(id: string, body: unknown) { return this.http.put<ApiShare>(`${this.baseUrl}/activities/${encodeURIComponent(id)}/share`, body); }
  revokeShare(id: string) { return this.http.delete<ApiShare>(`${this.baseUrl}/activities/${encodeURIComponent(id)}/share`); }
  mutation<T>(method: 'post' | 'put' | 'delete', path: string, body?: unknown) { return this.http.request<T>(method, `${this.baseUrl}${path}`, { body }); }
}

@Injectable({ providedIn: 'root' })
export class AuthStore {
  readonly status = signal<'loading' | 'authenticated' | 'anonymous'>('loading'); readonly authenticated = computed(() => this.status() === 'authenticated'); readonly user = signal<ApiUser | null>(null); readonly preferences = signal<ApiPreferences>({}); readonly error = signal('');
  private init$?: Observable<boolean>; private readonly api = inject(ApiService); private readonly csrf = inject(CsrfStore);
  initialize(force = false) { if (force) this.init$ = undefined; if (!this.init$) this.init$ = this.api.session().pipe(tap(session => this.applySession(session)), map(session => session.authenticated), catchError(() => { this.status.set('anonymous'); this.user.set(null); return of(false); }), shareReplay(1)); return this.init$; }
  refreshSession() { return this.initialize(true); }
  private applySession(session: ApiSession) { this.csrf.set(session.csrf_token); this.user.set(session.user); this.preferences.set(session.preferences ?? {}); this.status.set(session.authenticated ? 'authenticated' : 'anonymous'); }
  setError(message: string) { this.error.set(message); }
  loginWithStrava() { this.error.set(''); this.api.stravaAuthorization().subscribe({ next: response => { if (response.authorization_url && typeof window !== 'undefined') window.location.assign(response.authorization_url); else this.error.set('La API no ha devuelto una URL válida de Strava.'); }, error: () => this.error.set('No se ha podido iniciar la conexión con Strava.') }); }
  logout() { this.init$ = undefined; this.user.set(null); this.status.set('anonymous'); this.api.mutation<{ ok: boolean }>('post', '/auth/logout').pipe(catchError(() => of({ ok: false }))).subscribe(() => this.csrf.clear()); }
}

@Injectable({ providedIn: 'root' })
export class SportsDataStore {
  readonly activities = signal<Activity[]>([]); readonly segments = signal<Segment[]>([]); readonly dashboard = signal<ApiDashboard | null>(null); readonly pagination = signal<ActivityPagination>({ limit: 100, cursor: null, has_next: false, next_cursor: null }); readonly loading = signal(false); readonly error = signal(''); private readonly api = inject(ApiService);
  loadDashboard(force = false) { if (this.dashboard() && !force) return; this.loading.set(true); this.api.dashboard().subscribe({ next: value => this.dashboard.set(value), error: () => this.error.set('No se ha podido cargar el resumen.'), complete: () => this.loading.set(false) }); }
  loadActivities(force = false) { if (this.activities().length && !force) return; this.loading.set(true); this.api.activities(100).subscribe({ next: response => { this.activities.set(response.activities.map(item => this.toActivity(item))); if (response.pagination) this.pagination.set(response.pagination); }, error: () => this.error.set('No se han podido cargar las actividades.'), complete: () => this.loading.set(false) }); }
  loadMoreActivities() { const page = this.pagination(); if (!page.has_next || !page.next_cursor) return; this.loading.set(true); this.api.activities(page.limit, page.next_cursor).subscribe({ next: response => { this.activities.update(items => [...items, ...response.activities.map(item => this.toActivity(item))]); if (response.pagination) this.pagination.set(response.pagination); }, error: () => this.error.set('No se han podido cargar más actividades.'), complete: () => this.loading.set(false) }); }
  refresh() { this.dashboard.set(null); this.activities.set([]); this.pagination.set({ limit: 100, cursor: null, has_next: false, next_cursor: null }); this.loadDashboard(true); this.loadActivities(true); this.loadSegments(true); }
  loadSegments(force = false) { if (this.segments().length && !force) return; this.api.segments().subscribe({ next: response => this.segments.set((response.segments ?? []).map(item => this.toSegment(item))), error: () => this.error.set('No se han podido cargar los segmentos.') }); }
  toActivity(raw: unknown): Activity { const item: any = raw ?? {}; const sport = this.sport(item.sport_type); const distance = Number(item.distance ?? 0) / 1000; const moving = Number(item.moving_time ?? 0); const speed = Number(item.average_speed ?? 0); return { id: String(item.id), name: String(item.name ?? 'Actividad sin nombre'), sport_type: sport, date: this.dateLabel(item.start_date_local ?? item.start_date), distance, moving_time: Math.round(moving / 60), elevation: Math.round(Number(item.total_elevation_gain ?? 0)), pace: sport === 'Ride' ? `${(speed * 3.6).toFixed(1)} km/h` : this.pace(speed, distance), effort: Number(item.perceived_exertion ?? 0), color: sport === 'Ride' ? '#76a8ff' : sport === 'Walk' ? '#f0a45d' : '#c9f45b', location: String(item.location_city ?? item.city ?? item.location ?? 'Sin ubicación') }; }
  toSegment(raw: unknown): Segment { const item: any = raw ?? {}; const distance = Number(item.distance ?? 0); return { id: String(item.id), name: String(item.name ?? 'Segmento'), distance: typeof item.distance === 'string' ? item.distance : `${(distance / 1000).toFixed(2)} km`, elevation: `+${Math.round(Number(item.elevation_gain ?? item.total_elevation_gain ?? 0))} m`, best: this.duration(Number(item.best_time ?? item.pr_time ?? 0)), attempts: Number(item.attempts ?? item.effort_count ?? 0), rank: item.rank ? String(item.rank) : '—', color: '#c9f45b', trend: [34, 27, 30, 22, 24, 16, 19, 12] }; }
  private sport(value: unknown): Sport { return String(value).toLowerCase().includes('ride') || String(value).toLowerCase().includes('cycl') ? 'Ride' : String(value).toLowerCase().includes('walk') ? 'Walk' : 'Run'; }
  private pace(speed: number, distance: number) { const seconds = speed > 0 ? 1000 / speed : distance > 0 ? 3600 / distance : 0; return seconds ? `${Math.floor(seconds / 60)}:${String(Math.round(seconds % 60)).padStart(2, '0')} /km` : '—'; }
  private duration(seconds: number) { return seconds ? `${Math.floor(seconds / 60)}:${String(Math.round(seconds % 60)).padStart(2, '0')}` : '—'; }
  private dateLabel(value: unknown) { return value ? String(value).replace('T', ' · ').slice(0, 22) : 'Sin fecha'; }
}

