@Component({ selector: 'app-mini-chart', template: `<svg class="mini-chart" viewBox="0 0 240 64" preserveAspectRatio="none" aria-label="Gráfica de evolución"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#c9f45b" stop-opacity=".25"/><stop offset="1" stop-color="#c9f45b" stop-opacity="0"/></linearGradient></defs><path [attr.d]="area()" fill="url(#fill)"/><path [attr.d]="line()" fill="none" stroke="#c9f45b" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><circle [attr.cx]="lastPoint().x" [attr.cy]="lastPoint().y" r="3.5" fill="#c9f45b" stroke="#121510" stroke-width="2"/></svg>`, changeDetection: ChangeDetectionStrategy.OnPush })
export class MiniChart { readonly values = input<number[] | undefined>(); readonly data = computed(() => this.values()?.length ? this.values()! : [18, 23, 19, 32, 27, 38, 36, 45, 42, 56, 52, 62]); readonly coords = computed(() => { const values = this.data(); const max = Math.max(...values); const min = Math.min(...values); return values.map((value, index) => ({ x: (index / Math.max(values.length - 1, 1)) * 240, y: 56 - ((value - min) / (max - min || 1)) * 44 })); }); readonly line = computed(() => this.coords().map((point, index) => `${index ? 'L' : 'M'} ${point.x.toFixed(1)} ${point.y.toFixed(1)}`).join(' ')); readonly area = computed(() => `${this.line()} L 240 64 L 0 64 Z`); readonly lastPoint = computed(() => this.coords().at(-1) ?? { x: 240, y: 24 }); }

