@Component({ selector: 'app-segment-spark', inputs: ['data', 'color'], template: '<svg class="segment-spark"><path [attr.d]="path()" [attr.stroke]="color" fill="none" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" /></svg>', changeDetection: ChangeDetectionStrategy.OnPush })
export class SegmentSpark { data: number[] = []; color = '#c9f45b'; path = computed(() => { const values = this.data?.length ? this.data : [1, 2]; const max = Math.max(...values); const min = Math.min(...values); return values.map((value, index) => `${index ? 'L' : 'M'} ${(index / (values.length - 1)) * 130} ${(34 - ((value - min) / (max - min || 1)) * 26).toFixed(1)}`).join(' '); }); }

@Component({ selector: 'app-route-map', template: `<div class="route-map leaflet-shell"><div #map class="leaflet-host"></div><div class="map-label">MADRID <span>•</span> RETIRO</div><div class="map-legend"><span><i class="start-dot"></i> Inicio</span><span><i class="end-dot"></i> Final</span><span class="map-duration">45:02</span></div></div>`, changeDetection: ChangeDetectionStrategy.OnPush })
export class RouteMap implements AfterViewInit, OnDestroy {
  @ViewChild('map', { static: true }) private mapElement!: ElementRef<HTMLDivElement>;
  readonly routePoints = input<L.LatLngExpression[]>(DEFAULT_ROUTE);
  private map?: L.Map;
  private routeLayer?: L.LayerGroup;
  private pointsLayer?: L.LayerGroup;
  private readonly redraw = effect(() => { const points = this.routePoints(); if (this.map && points.length) this.drawRoute(points); });

  ngAfterViewInit() {
    if (typeof window === 'undefined') return;
    const cartoDark = L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', { attribution: '&copy; OpenStreetMap &copy; CARTO', maxZoom: 19 });
    const osm = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { attribution: '&copy; OpenStreetMap contributors', maxZoom: 19 });
    const topo = L.tileLayer('https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png', { attribution: '&copy; OpenStreetMap contributors, SRTM | OpenTopoMap', maxZoom: 17 });
    this.map = L.map(this.mapElement.nativeElement, { zoomControl: false, layers: [cartoDark] }).setView([40.4168, -3.7038], 13);
    L.control.zoom({ position: 'bottomright' }).addTo(this.map);
    L.control.scale({ imperial: false, position: 'bottomleft' }).addTo(this.map);
    this.routeLayer = L.layerGroup().addTo(this.map);
    this.pointsLayer = L.layerGroup().addTo(this.map);
    L.control.layers({ 'Alon Dark': cartoDark, 'OpenStreetMap': osm, 'Relieve': topo }, { 'Recorrido': this.routeLayer, 'Puntos clave': this.pointsLayer }, { collapsed: true, position: 'topright' }).addTo(this.map);
    this.drawRoute(this.routePoints());
    window.setTimeout(() => this.map?.invalidateSize(), 0);
  }

  private drawRoute(points: L.LatLngExpression[]) {
    if (!this.map || !this.routeLayer || !this.pointsLayer || points.length < 2) return;
    this.routeLayer.clearLayers(); this.pointsLayer.clearLayers();
    const coords = points.map(point => L.latLng(point));
    L.polyline(coords, { color: '#081008', weight: 10, opacity: .8, lineCap: 'round', lineJoin: 'round' }).addTo(this.routeLayer);
    L.polyline(coords, { color: '#c9f45b', weight: 5, opacity: 1, lineCap: 'round', lineJoin: 'round' }).addTo(this.routeLayer);
    const startIcon = L.divIcon({ className: 'leaflet-route-marker', html: '<span class="marker-start"></span>', iconSize: [18, 18], iconAnchor: [9, 9] });
    const finishIcon = L.divIcon({ className: 'leaflet-route-marker', html: '<span class="marker-finish"></span>', iconSize: [18, 18], iconAnchor: [9, 9] });
    L.marker(coords[0], { icon: startIcon }).bindTooltip('Inicio', { direction: 'top', offset: [0, -8] }).addTo(this.pointsLayer);
    L.marker(coords.at(-1)!, { icon: finishIcon }).bindTooltip('Final · 45:02', { direction: 'top', offset: [0, -8] }).addTo(this.pointsLayer);
    L.circleMarker(coords[Math.floor(coords.length / 2)], { radius: 5, color: '#16200b', weight: 2, fillColor: '#ffffff', fillOpacity: 1 }).bindPopup('<strong>Segmento destacado</strong><br>Cuesta de Moyano · 3:42').addTo(this.pointsLayer);
    this.map.fitBounds(L.latLngBounds(coords), { padding: [28, 28] });
  }

  ngOnDestroy() { this.redraw.destroy(); this.map?.remove(); }
}

